	if err = a.L.LoadUfiUsuarioFilials(ctx, tx, true, &a, nil); err != nil {
		t.Fatal(err)
	}
	if got := len(a.R.UfiUsuarioFilials); got != 2 {
		t.Error("number of eager loaded records wrong, got:", got)
	}

